// Consolida resultado de qualquer canal em um formato unificado
const result    = $input.first().json;
const reminder  = $('Dividir por Lembrete').item.json;
const channel   = reminder.channel;

// Detecta sucesso por canal
const waSuccess    = !!(result.messages?.[0]?.id || result.success);
const emailSuccess = result.success === true || !!result.resend_id;
const isSuccess    = channel === 'whatsapp' ? waSuccess : emailSuccess;

// Detecta erros não-retriáveis (telefone inválido, template não aprovado, etc.)
const errorMsg  = result.error ?? result.message ?? null;
const nonRetryablePatterns = ['invalid_phone','template_not_found','template_not_approved','131030','131047','100'];
const retryable = errorMsg
  ? !nonRetryablePatterns.some(p => String(errorMsg).toLowerCase().includes(p.toLowerCase()))
  : true;

const providerId = result.messages?.[0]?.id ?? result.resend_id ?? null;

console.log(`[reminder] ${channel} | appt=${reminder.appointment_id} | ${isSuccess ? 'SENT ' + (providerId ?? '') : 'FAILED: ' + errorMsg}`);

return [{
  json: {
    reminder_id:         reminder.id,
    appointment_id:      reminder.appointment_id,
    channel,
    success:             isSuccess,
    provider_message_id: providerId,
    error:               isSuccess ? null : (errorMsg ?? 'unknown_error'),
    retryable:           isSuccess ? null : retryable,
  }
}];
